"""Baut data/mechanics.json (Spielmechaniken & Fortschrittssysteme, Dead Cells 3.5).
Inhalte: eigene deutsche Zusammenfassungen auf Basis der gecachten Wiki-Seiten in
research/cache/mechanics/pages/ (deadcells.wiki.gg, abgerufen 2026-10) plus Patchnotes 3.5.
Deutsche Spielnamen (nameDe) kommen aus data/names-de.json (Spiel-Lokalisierung)."""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
W = "https://deadcells.wiki.gg/wiki/"
NAMES_DE = json.loads((ROOT / "data" / "names-de.json").read_text(encoding="utf-8"))


def de(name):
    return NAMES_DE.get(name)


def sec(id, title, summary, points, wiki):
    return {"id": id, "title": title, "icon": None, "summary": summary, "points": points,
            "wiki": W + wiki.replace(" ", "_")}


