def up(name, cat, cells, effect, rec, why, requires=None, minBC=0):
    return {"name": name, "nameDe": de(name), "category": cat, "cells": cells, "minBC": minBC,
            "effect": effect, "recommended": rec, "why": why, "requires": requires}

